from pathlib import Path
p=Path('outputs/ROMDex/rom/location-decoder.mjs');s=p.read_text(encoding='utf-8-sig');s=s.replace("for(const match of info.matchAll(/^\\s*Name:\\s*(.+)$/gm)){let name=match[1].trim();", "// Only top-level model/texture/palette names become output filenames.\n // Nested material labels may legally contain ':' and stay inside the GLB JSON.\n for(const match of info.matchAll(/^ {0,2}Name:\\s*(.+)$/gm)){let name=match[1].trim();")
p.write_text(s,encoding='utf-8')
p=Path('outputs/ROMDex/tests/location-portability.test.mjs');s=p.read_text(encoding='utf-8-sig');s+='''\n\ntest('nested material labels may contain punctuation without becoming decoder filenames',()=>{verifyMaterialBindings('Got 1 model, 1 texture, 1 palette.\\nModel 0:\\n  Name: safe_model\\n    Material 0:\\n      Name: "stair_u02:shade"\\nTexture 0:\\n  Name: safe_texture\\nPalette 0:\\n  Name: safe_palette');});\nfor(const kind of ['Model','Texture','Palette'])test('unsafe top-level '+kind+' filenames remain rejected',()=>{for(const name of ['../outside','"bad:name"','"sub/file"'])assert.throws(()=>verifyMaterialBindings('Got 1 model, 1 texture, 1 palette.\\n'+kind+' 0:\\n  Name: '+name),/Safe Decoder Filename/);});\n''';p.write_text(s,encoding='utf-8')
